solution:
INSTALL h3 FROM community;
LOAD h3;

SELECT h3_h3_to_string(h3_latlng_to_cell(pickup_lat, pickup_lon, 7)) AS h3_cell,
       COUNT(*) AS pickups
FROM read_parquet('./data/nyc_taxi_sample.parquet')
GROUP BY h3_cell
ORDER BY pickups DESC, h3_cell
LIMIT 5;
